          if (btn.id === "tabBtnSynthGlobal" && (!canSeeGlobalSynth() || !isMarketOnlyViewer() && getEffectiveAmFilter() !== "ALL")) return;
          if (btn.id === "tabBtnCommissions" && !isOwnerAdmin()) return;
